function millisecondsToHMS(inputMilliseconds) {
  // Calculate the hours, minutes, and seconds using bitwise operators.
  const hours = inputMilliseconds / 3600000 | 0;
  const minutes = (inputMilliseconds / 60000) & 63;
  const seconds = (inputMilliseconds / 1000) & 63;
  const milliseconds = inputMilliseconds & 1023;

  // Format the time.
  const formattedTime = `${hours}:${minutes}:${seconds}.${milliseconds}`;

  return formattedTime;
}

rewrite this bfs solution:

class Solution:
    def countCompleteComponents(self, n: int, edges: List[List[int]]) -> int:

        graph = [[] for i in range(n)]

        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        seen = [0] * n
        ans = 0

        for i in range(n):
            if seen[i]:
                continue

            bfs = [i]
            seen[i] = 1

            for j in bfs:
                for k in graph[j]:
                    if seen[k] == 0:
                        bfs.append(k)
                        seen[k] = 1

            if all(len(graph[j]) == len(bfs) - 1 for j in bfs):
                ans += 1

        return ans

void resizecmat(CMat* A, int r, int c)
{
	if (A == NULL) return;
	if ((A->row == r) && (A->col == c))
		return;

	for (int ri = 0; ri < A->row; ri++)
		tfree(A->d[ri]);

	if (A->d != NULL)
		tfree(A->d);

	A->row = r; A->col = c;
	A->d = (cplx**)tmalloc(sizeof(cplx*) * (size_t)r);

	if (A->d == NULL) return;

	for (int i = 0; i < r; i++)
		A->d[i] = (cplx*)tmalloc(sizeof(cplx) * (size_t)c);
}

